"use client"

import { useMemo, useState } from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import type { LiveCandidate, LiveDecision, LiveStrategy } from "@/lib/live/types"

const money = new Intl.NumberFormat("en-GB", {
  style: "currency",
  currency: "EUR",
  maximumFractionDigits: 2,
})

const qty = new Intl.NumberFormat("en-GB")

function euros(value: string): string {
  const parsed = Number(value)
  return Number.isFinite(parsed) ? money.format(parsed) : value
}

/** "2026-09-14" reads as a date, not a string, at a glance. */
function shortDate(iso: string): string {
  const parsed = new Date(iso)
  if (Number.isNaN(parsed.getTime())) return iso
  return parsed.toLocaleDateString("en-GB", { day: "numeric", month: "short" })
}

function supplierName(
  ref: string,
  candidates: readonly LiveCandidate[]
): string {
  return candidates.find((c) => c.supplier_ref === ref)?.supplier_name ?? ref
}

/** Cost above the recommended plan, which is what makes a runner-up a runner-up. */
function delta(option: LiveStrategy, best: LiveStrategy): string | null {
  const gap = Number(option.total_cost) - Number(best.total_cost)
  if (!Number.isFinite(gap) || gap <= 0) return null
  return `+${money.format(gap)}`
}

export function DecisionPanel({
  decision,
  candidates,
  caseId,
}: {
  decision: LiveDecision | null
  candidates: readonly LiveCandidate[]
  caseId: string | null
}) {
  const [showAll, setShowAll] = useState(false)

  const { best, runnersUp } = useMemo(() => {
    const options = decision?.options ?? []
    const winner =
      options.find((o) => o.recommended) ??
      options.find((o) => o.strategy_id === decision?.recommended_strategy_id) ??
      options[0] ??
      null
    return {
      best: winner,
      runnersUp: options.filter((o) => o !== winner),
    }
  }, [decision])

  const rejected = candidates.filter((c) => !c.compliance.passed)

  if (!decision || !best) return null

  return (
    <section
      aria-label="Recommendation"
      className="overflow-hidden rounded-xl border border-border bg-card"
    >
      <header className="flex items-center gap-2 border-b border-border bg-muted/40 px-4 py-2.5">
        <span className="text-xs font-medium tracking-wide text-muted-foreground uppercase">
          Recommendation
        </span>
        <Badge
          variant={best.meets_line_stop ? "default" : "destructive"}
          className="ml-auto"
        >
          {best.meets_line_stop ? "Beats the line stop" : "Misses the line stop"}
        </Badge>
      </header>

      <div className="px-4 py-4">
        <p className="text-base leading-snug font-medium text-balance">
          {best.label}
        </p>

        <dl className="mt-4 grid grid-cols-2 gap-x-4 gap-y-3 sm:grid-cols-4">
          <Figure label="Total cost" value={euros(best.total_cost)} emphasis />
          <Figure
            label="Effective unit"
            value={`${euros(best.unit_effective)}`}
          />
          <Figure label="Covered by" value={shortDate(best.coverage_date)} />
          <Figure label="Plans priced" value={String(decision.options.length)} />
        </dl>

        <ul className="mt-4 flex flex-col gap-1.5">
          {best.suppliers.map((line) => (
            <li
              key={`${line.supplier_ref}-${line.eta}`}
              className="flex items-baseline gap-2 rounded-md bg-muted/40 px-3 py-2 text-sm"
            >
              <span className="font-medium">
                {supplierName(line.supplier_ref, candidates)}
              </span>
              <span className="text-muted-foreground tabular-nums">
                {qty.format(line.qty)} pcs
              </span>
              <span className="ml-auto text-xs text-muted-foreground tabular-nums">
                arrives {shortDate(line.eta)}
              </span>
            </li>
          ))}
        </ul>
      </div>

      {runnersUp.length > 0 ? (
        <div className="border-t border-border px-4 py-3">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="-mx-2 h-auto px-2 py-1 text-xs text-muted-foreground"
            aria-expanded={showAll}
            onClick={() => setShowAll((open) => !open)}
          >
            {showAll ? "Hide" : "Show"} {runnersUp.length} other plan
            {runnersUp.length === 1 ? "" : "s"}
          </Button>

          {showAll ? (
            <ul className="mt-2 flex flex-col gap-1">
              {runnersUp.map((option) => (
                <li
                  key={option.strategy_id}
                  className="flex items-baseline gap-3 border-t border-border/60 py-2 text-sm first:border-t-0"
                >
                  <span className="min-w-0 flex-1 truncate text-muted-foreground">
                    {option.label}
                  </span>
                  <span className="tabular-nums">
                    {euros(option.total_cost)}
                  </span>
                  <span className="w-20 text-right text-xs text-amber-600 tabular-nums">
                    {delta(option, best) ?? ""}
                  </span>
                </li>
              ))}
            </ul>
          ) : null}
        </div>
      ) : null}

      {rejected.length > 0 ? (
        <div className="border-t border-border px-4 py-3">
          <p className="text-xs font-medium tracking-wide text-muted-foreground uppercase">
            Rejected on policy
          </p>
          <ul className="mt-2 flex flex-col gap-1.5">
            {rejected.map((candidate) => (
              <li
                key={candidate.supplier_ref}
                className="flex items-baseline gap-2 text-sm"
              >
                <span className="text-muted-foreground line-through">
                  {candidate.supplier_name}
                </span>
                <span className="flex flex-wrap gap-1">
                  {candidate.compliance.failed_rules.map((rule) => (
                    <code
                      key={rule}
                      className="rounded bg-destructive/10 px-1.5 py-0.5 font-mono text-[11px] text-destructive"
                    >
                      {rule}
                    </code>
                  ))}
                </span>
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      <footer className="flex flex-wrap items-center gap-x-3 gap-y-1 border-t border-border bg-muted/30 px-4 py-2.5">
        <p className="text-xs text-muted-foreground">{decision.approval}</p>
        {caseId ? (
          <a
            href={`/backend/cases/${encodeURIComponent(caseId)}/artifacts/decision.md`}
            target="_blank"
            rel="noreferrer"
            className="ml-auto text-xs underline underline-offset-4"
          >
            Read decision.md
          </a>
        ) : null}
      </footer>
    </section>
  )
}

function Figure({
  label,
  value,
  emphasis = false,
}: {
  label: string
  value: string
  emphasis?: boolean
}) {
  return (
    <div className="flex flex-col gap-0.5">
      <dt className="text-[11px] tracking-wide text-muted-foreground uppercase">
        {label}
      </dt>
      <dd
        className={
