const before = radios.map(r => r.getAttribute('aria-checked'));
radios[1]?.click();
await new Promise(r => setTimeout(r, 400));
const after = [...document.querySelectorAll('[role="radio"]')].map(r => r.getAttribute('aria-checked'));
JSON.stringify({ count: radios.length, before, after });
